" y2=\"380\" stroke=\"#8b5cf6\" stroke-width=\"2\" stroke-dasharray=\"6\" opacity=\"0.6\"/><line x1=\"550\" y1=\"600\" x2=\"550\" y2=\"550\" stroke=\"#10b981\" stroke-width=\"2\" stroke-dasharray=\"6\" opacity=\"0.6\"/></svg>",
