      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Cupid's disease as excess</text><rect x=\"150\" y=\"220\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"24\">TREPONEMA PALLIDUM</text><text x=\"550\" y=\"340\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">cortical inflammation disinhibits</text><text x=\"550\" y=\"385\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">surplus of drive, mood, appetite</text><rect x=\"250\" y=\"470\" width=\"600\" height=\"90\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"525\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Organism and why it's an 'excess'?</text></svg>",
