      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE AURA EXPANDS</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">A wave across the visual field</text><circle cx=\"550\" cy=\"430\" r=\"40\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"3\"/><circle cx=\"550\" cy=\"430\" r=\"100\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"3\" stroke-dasharray=\"10\" opacity=\"0.8\"/><circle cx=\"550\" cy=\"430\" r=\"170\" fill=\"none\" stroke=\"#ffd700\" stroke-width=\"3\" stroke-dasharray=\"10\" opacity=\"0.6\"/><circle cx=\"550\" cy=\"430\" r=\"240\" fill=\"none\" stroke=\"#ffd700\" stroke-width=\"3\" stroke-dasharray=\"10\" opacity=\"0.4\"/><text x=\"550\" y=\"437\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"18\">start</text><path d=\"M620 360 L660 320\" stroke=\"#10b981\" stroke-width=\"3\"/><polygon points=\"660,320 644,326 654,336\" fill=\"#10b981\"/><text x=\"720\" y=\"320\" text-anchor=\"start\" fill=\"#10b981\" font-size=\"17\">expands over minutes</text><rect x=\"150\" y=\"730\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"785\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Scintillating scotoma with zigzag edges</text><text x=\"550\" y=\"823\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">cortical spreading depression made visible</text></svg>",
