      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">WISDOM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Not lies, but states of meaning</text><rect x=\"100\" y=\"250\" width=\"900\" height=\"380\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"150\" y=\"325\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">\"She interprets this, in accordance with</text><text x=\"150\" y=\"368\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">her religious disposition, as inspiration</text><text x=\"150\" y=\"411\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">or grace... Such visions are not lies or</text><text x=\"150\" y=\"454\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">delusions: they may be extraordinary</text><text x=\"150\" y=\"497\" text-anchor=\"start\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">states of feeling and meaning.\"</text><text x=\"950\" y=\"585\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"19\">— after Oliver Sacks</text></svg>",
